// Parse and extract alert information
const text = $input.item.json.text || '';

// Extract severity
let severity = 'UNKNOWN';
if (text.includes('🔴') || text.includes('[CRITICAL]')) {
  severity = 'CRITICAL';
} else if (text.includes('🟠') || text.includes('[HIGH]')) {
  severity = 'HIGH';
} else if (text.includes('🟡') || text.includes('[MEDIUM]')) {
  severity = 'MEDIUM';
} else if (text.includes('🟢') || text.includes('[LOW]')) {
  severity = 'LOW';
}

// Extract service name
const serviceMatch = text.match(/\*Service:\*\s*`([^`]+)`/);
const service = serviceMatch ? serviceMatch[1] : 'unknown-service';

// Extract environment
const envMatch = text.match(/\*Environment:\*\s*`([^`]+)`/);
const environment = envMatch ? envMatch[1] : 'production';

// Extract error type and map to relevant code files
let errorType = 'Unknown Error';
let relevantFiles = [];

if (text.includes('Database') || text.includes('database') || text.includes('Connection Pool')) {
  errorType = 'Database Error';
  relevantFiles = [
    'OrderService.java',
    'OrderRepository.java',
    'DatabaseTimeoutException.java',
    'application.yml'
  ];
} else if (text.includes('Payment') || text.includes('payment')) {
  errorType = 'Payment Gateway Error';
  relevantFiles = [
    'PaymentService.java',
    'PaymentController.java',
    'PaymentGatewayException.java'
  ];
} else if (text.includes('Inventory') || text.includes('inventory')) {
  errorType = 'Inventory Service Error';
  relevantFiles = [
    'InventoryService.java',
    'OrderService.java',
    'InventoryException.java'
  ];
} else if (text.includes('Memory') || text.includes('memory')) {
  errorType = 'Memory Issue';
  relevantFiles = [
    'OrderService.java',
    'MetricsService.java',
    'application.yml'
  ];
} else if (text.includes('Timeout') || text.includes('timeout')) {
  errorType = 'Timeout Error';
  relevantFiles = [
    'OrderService.java',
    'PaymentService.java',
    'application.yml'
  ];
}

// Extract error rate if present
const errorRateMatch = text.match(/(\d+)%/);
const errorRate = errorRateMatch ? parseInt(errorRateMatch[1]) : 0;

// Extract timestamp
const timeMatch = text.match(/\*Time:\*\s*([^\n]+)/);
const timestamp = timeMatch ? timeMatch[1] : new Date().toISOString();

// Determine if this needs immediate escalation
const needsEscalation = severity === 'CRITICAL' || errorRate > 40;

return {
  json: {
    originalText: text,
    severity: severity,
    service: service,
    environment: environment,
    errorType: errorType,
    errorRate: errorRate,
    timestamp: timestamp,
    needsEscalation: needsEscalation,
    relevantFiles: relevantFiles,
    channel: $input.item.json.channel,
    threadTs: $input.item.json.ts,
    user: $input.item.json.user
  }
};

// Load relevant source code files based on error type
const fs = require('fs');
const path = require('path');

const relevantFiles = $input.item.json.relevantFiles || [];
const basePath = '/Users/sunil.kunda/ApplicationCode/POC/hackathon-2025/sample-app/src/main/java/com/example/orderservice';
const resourcesPath = '/Users/sunil.kunda/ApplicationCode/POC/hackathon-2025/sample-app/src/main/resources';

let codeContext = '**Relevant Application Code:**\n\n';

for (const file of relevantFiles) {
  try {
    let filePath;

    // Determine file location
    if (file === 'application.yml') {
      filePath = path.join(resourcesPath, file);
    } else if (file.includes('Service.java')) {
      filePath = path.join(basePath, 'service', file);
    } else if (file.includes('Controller.java')) {
      filePath = path.join(basePath, 'controller', file);
    } else if (file.includes('Repository.java')) {
      filePath = path.join(basePath, 'repository', file);
    } else if (file.includes('Exception.java')) {
      filePath = path.join(basePath, 'exception', file);
    } else {
      filePath = path.join(basePath, file);
    }

    // Read file if it exists
    if (fs.existsSync(filePath)) {
      const content = fs.readFileSync(filePath, 'utf8');

      // Truncate if too long (keep first 100 lines)
      const lines = content.split('\n').slice(0, 100);
      const truncated = lines.join('\n');

      codeContext += `### ${file}\n\`\`\`java\n${truncated}\n\`\`\`\n\n`;
    }
  } catch (error) {
    console.log(`Could not read file ${file}: ${error.message}`);
  }
}

// If no files were loaded, add a note
if (codeContext === '**Relevant Application Code:**\n\n') {
  codeContext += '*No specific code files identified for this error type.*\n';
}

return {
  json: {
    ...($input.item.json),
    codeContext: codeContext
  }
};

// Format AI response for Slack
const severity = $('Parse Alert & Identify Files').item.json.severity;
const service = $('Parse Alert & Identify Files').item.json.service;
const errorType = $('Parse Alert & Identify Files').item.json.errorType;
const relevantFiles = $('Parse Alert & Identify Files').item.json.relevantFiles || [];
const aiOutput = $input.item.json.output;

const severityEmoji = {
  'CRITICAL': '🔴',
  'HIGH': '🟠',
  'MEDIUM': '🟡',
  'LOW': '🟢'
}[severity] || '⚪';

const filesAnalyzed = relevantFiles.length > 0 
  ? `\n**Code Files Analyzed:** ${relevantFiles.map(f => `\`${f}\``).join(', ')}\n`
  : '';

const formattedResponse = `${severityEmoji} **Alert Analysis Complete (with Code Context)**

**Service:** \`${service}\`
**Error Type:** ${errorType}
**Severity:** ${severity}${filesAnalyzed}

---

${aiOutput}

---

*Analysis generated at ${new Date().toISOString()}*
*Powered by AI Alert Analyzer with Code Context*`;

return {
  json: {
    formattedResponse: formattedResponse,
    severity: severity,
    service: service,
    channel: $('Parse Alert & Identify Files').item.json.channel,
    threadTs: $('Parse Alert & Identify Files').item.json.threadTs
  }
};

